let hash

function preload(){
  hash = fxhash
  seed = fxrand()*999999999
  randomSeed(seed)

}


function restart(){
  minl = Math.min(windowWidth, windowHeight)
  resizeCanvas(minl, minl)
  textSize(minl / 35);
  background(0);
  for (let i = 0; i < 250; i++){
    text(hash, random(width), random(height));
  }
}

function setup() { 
  createCanvas(2000, 2000);
  textFont('Georgia');
  textAlign(CENTER, CENTER);
  stroke(random(255),random(255),random(255))
  restart()
  }


function draw() {
  
  let time = millis();
  
  text(hash, random(width), random(height));
}

function windowResized() {
  restart()
}